def iso(y, m, d):
    return date(int(y), int(m), int(d)).isoformat()


def mon_date(s):
    m = re.fullmatch(r"(\d{1,2})[ -]([A-Za-z]+)[ -](\d{4})", s.strip())
    if not m:
        raise ValueError(s)
    return iso(m[3], MONTHS[m[2][:3].lower()], m[1])


def dmy(s):
    m = re.fullmatch(r"(\d{1,2})[./](\d{1,2})[./](\d{4})", s.strip())
    if not m:
        raise ValueError(s)
    return iso(m[3], m[2], m[1])


def country_of(raw):
    if not raw or not raw.strip():
        return None
    return COUNTRY[raw.strip().lower().replace(".", "")]


def tokens(s):
    s = re.sub(r"\([^)]*\)", " ", s).replace(".", " ")
    keep = [t for t in s.split()
            if t.lower() not in TITLES and not (len(t) == 1 and t.isalpha())]
    return " ".join(keep)


def split_name(raw, system):
    raw = raw.strip()
    if "," in raw:
        fam, giv = raw.split(",", 1)
        return tokens(giv), tokens(fam)
    parts = tokens(raw).split()
    if system == "KOBO":
        return " ".join(parts[1:]), parts[0]
    return " ".join(parts[:-1]), parts[-1]


def formal(given):
    return NICK.get(given.lower(), given)


def fix_case(s):
    return s.title() if s.isupper() else s


def renderings(s):
    s = s.lower().replace("'", "").replace(" ", "")
    options = []
    for ch in s:
        if ch in RENDER:
            options.append(RENDER[ch])
        else:
            options.append([unicodedata.normalize("NFD", ch)[0]])
    return {"".join(c) for c in product(*options)}


def osa(a, b):
    d = [[0] * (len(b) + 1) for _ in range(len(a) + 1)]
    for i in range(len(a) + 1):
        d[i][0] = i
    for j in range(len(b) + 1):
        d[0][j] = j
    for i in range(1, len(a) + 1):
        for j in range(1, len(b) + 1):
            cost = 0 if a[i - 1] == b[j - 1] else 1
            d[i][j] = min(d[i - 1][j] + 1, d[i][j - 1] + 1, d[i - 1][j - 1] + cost)
            if i > 1 and j > 1 and a[i - 1] == b[j - 2] and a[i - 2] == b[j - 1]:
                d[i][j] = min(d[i][j], d[i - 2][j - 2] + 1)
    return d[len(a)][len(b)]


def name_dist(a, b):
    return min(osa(x, y) for x in renderings(a) for y in renderings(b))


def names_match(r1, r2):
    g = name_dist(formal(r1["given"]), formal(r2["given"]))
    f = name_dist(r1["family"], r2["family"])
    return g + f <= 1


def e164(raw, country, system):
    if not raw or not re.search(r"\d", raw):
        return None
    if set(re.sub(r"\D", "", raw)) == {"0"}:
        return None
    s = raw.replace("(0)", "").strip()
    if s.startswith("+"):
        return "+" + re.sub(r"\D", "", s)
    if system == "BRIGHTDESK" and s.startswith("011"):
        return "+" + re.sub(r"\D", "", s[3:])
    if s.startswith("00"):
        return "+" + re.sub(r"\D", "", s[2:])
    if country is None:
        return None
    d = re.sub(r"\D", "", s)
    if country in ("US", "CA"):
        if len(d) == 11 and d[0] == "1":
            d = d[1:]
    elif country in TRUNK0 and d.startswith("0"):
        d = d[1:]
    return "+" + CALLING[country] + d


def bd_dob(s):
    s = s.strip()
    if s == "00/00/0000" or not s:
        return None
    m = re.fullmatch(r"(\d{1,2})/(\d{1,2})/(\d{4})", s)
    if m:
        return iso(m[3], m[1], m[2])  # BRIGHTDESK numeric dates are month first
    return mon_date(s)


def atlas_dob(s):
    if s in ("", "n/k", "?"):
        return None
    if re.fullmatch(r"\d{1,2}/\d{1,2}/\d{4}", s):
        return dmy(s)
    return mon_date(s)


def kobo_dob(s):
    m = re.fullmatch(r"([SH])(\d+)\.(\d+)\.(\d+)", s)
    if m:
        base = 1925 if m[1] == "S" else 1988
        return iso(base + int(m[2]), m[3], m[4])
    m = re.fullmatch(r"(\d{4})/(\d{1,2})/(\d{1,2})", s)
    if m:
        return iso(m[1], m[2], m[3])
    return None


def parse_brightdesk(line):
    m = re.fullmatch(r"BRIGHTDESK row=(\d+) \| (.*)", line)
    f = {}
    for part in m[2].split(" | "):
        k, _, v = part.partition("=")
        f[k.strip()] = v.strip()
    given, family = split_name(f["name"], "BRIGHTDESK")
    bal = None
    raw = f["balance"]
    if re.search(r"\d", raw):
        neg = raw.startswith("(") or raw.startswith("-")
        num = re.search(r"\d[\d,]*(?:\.\d+)?", raw)[0].replace(",", "")
        bal = (Fraction(num) * (-1 if neg else 1), "USD")
    return dict(
        row=int(m[1]), system="BRIGHTDESK", ledgr=False,
        void=f["name"].startswith("ZZTEST") or f.get("stage") == "review",
        given=given, family=family, dob=bd_dob(f["dob"]),
        country=country_of(f.get("country")), phone_raw=f.get("phone"),
        bal=bal, date=f["updated"])


def parse_ledgr(line):
    p = line.split(";")
    assert p[0] == "LEDGR" and len(p) == 10, line
    given, family = split_name(p[2], "LEDGR")
    bal = None
    if re.search(r"\d", p[7]):
        ccy = "CHF" if "CHF" in p[7] else "EUR"
        num = re.search(r"\d[\d.,]*", p[7])[0].replace(".", "").replace(",", ".")
        bal = (Fraction(num) * (-1 if "-" in p[7] else 1), ccy)
    return dict(
        row=int(p[1]), system="LEDGR", ledgr=True, void=p[8].strip() == "storniert",
        given=given, family=family, dob=dmy(p[4]) if p[4].strip() else None,
        country=country_of(p[5]), phone_raw=p[6], bal=bal, date=dmy(p[9]))


def parse_atlas(line):
    p = [x.strip() for x in line.split("::")]
    given, family = split_name(p[1], "ATLAS")
    born = p[2][len("born"):].strip()
    owed = p[5][len("owed"):].strip()
    val = Fraction(re.search(r"\d[\d,]*(?:\.\d+)?", owed)[0].replace(",", ""))
    # "owed" is what we owe the supplier, so the master sign is opposite; CR is negative owed.
    master = val if owed.endswith("CR") else -val
    return dict(
        row=int(p[0].split("#")[1]), system="ATLAS", ledgr=False,
        void=any(x == "DO NOT MIGRATE" for x in p[7:]),
        given=given, family=family, dob=atlas_dob(born), country=country_of(p[3]),
        phone_raw=p[4][len("tel"):].strip(), bal=(master, "GBP"),
        date=mon_date(p[6][len("last change"):].strip()))


def parse_veritas(line):
    obj = json.loads(line[len("VERITAS "):])
    return dict(
        row=int(obj["row"]), system="VERITAS", ledgr=False,
        void=obj.get("env") == "sandbox",
        given=obj["given"], family=obj["family"],
        dob=None if obj["dob"] == "1900-01-01" else obj["dob"],
        country="GB" if obj["country"].upper() == "UK" else obj["country"].upper(),
        phone_raw=("+" + obj["msisdn"]) if obj["msisdn"] else None,
        bal=(Fraction(obj["amount"]), obj["ccy"]) if obj["amount"] else None,
        date=obj["ts"][:10])


def parse_kobo(line):
    m = re.fullmatch(r"KOBO/(\d+) (.*)", line)
    f = {}
    for part in m[2].split(" | "):
        k, _, v = part.partition(":")
        f[k.strip()] = v.strip()
    given, family = split_name(f["member"], "KOBO")
    raw = f["balance"]
    bal = None
    if re.search(r"\d", raw):
        neg = "▲" in raw or "-" in raw
        num = re.search(r"\d[\d,]*", raw)[0].replace(",", "")
        bal = (Fraction(num) * (-1 if neg else 1), "JPY")
    return dict(
        row=int(m[1]), system="KOBO", ledgr=False,
        void="SAMPLE" in f.get("flag", ""),
        given=given, family=family, dob=kobo_dob(f["birth"]), country="JP",
        phone_raw=f["tel"], bal=bal, date=f["upd"].replace("/", "-"))


def parse_vendex(line):
    m = re.match(r"Vendex (\d+) ", line)
    rid = int(m[1])
    if "Application withdrawn" in line:
        return dict(row=rid, system="VENDEX", ledgr=False, void=True)
    v = VENDEX[rid]
    bal = (Fraction(v["bal"][0]), v["bal"][1]) if v["bal"] else None
    return dict(
        row=rid, system="VENDEX", ledgr=False, void=False,
        given=v["given"], family=v["family"], dob=v["dob"], country=v["country"],
        phone_raw=v["phone"], bal=bal, date=v["date"])


def parse_line(line):
    if line.startswith("BRIGHTDESK "):
        return parse_brightdesk(line)
    if line.startswith("LEDGR;"):
        return parse_ledgr(line)
    if line.startswith("ATLAS #"):
        return parse_atlas(line)
    if line.startswith("VERITAS "):
        return parse_veritas(line)
    if line.startswith("KOBO/"):
        return parse_kobo(line)
    if line.startswith("Vendex "):
        return parse_vendex(line)
    raise ValueError(line)


def to_usd(val, ccy):
    op, rate = RATE[ccy]
    return val * rate if op == "mul" else val / rate


def round_half_away(x, places=2):
    q = abs(x) * 10 ** places
    v = Fraction(math.floor(q + Fraction(1, 2)), 10 ** places)
    return -v if x < 0 else v


rows = [parse_line(ln) for ln in lines]
print("lines:", len(lines), "void:", sum(r["void"] for r in rows))
for r in rows:
    if not r["void"]:
        r["phone"] = e164(r["phone_raw"], r["country"], r["system"])
live = [r for r in rows if not r["void"]]

# union-find over identity rules 3(a) and 3(b)
parent = {r["row"]: r["row"] for r in live}


def find(x):
    while parent[x] != x:
        parent[x] = parent[parent[x]]
        x = parent[x]
    return x


def same_person(a, b):
    if not names_match(a, b):
        return False
    if a["dob"] and b["dob"]:
        return a["dob"] == b["dob"]
    return bool(a["phone"]) and a["phone"] == b["phone"]


for i, a in enumerate(live):
    for b in live[i + 1:]:
        if same_person(a, b):
            parent[find(a["row"])] = find(b["row"])

groups = {}
for r in live:
    groups.setdefault(find(r["row"]), []).append(r)

records = []
for members in groups.values():
    order = sorted(members, key=lambda r: r["date"], reverse=True)
    order.sort(key=lambda r: r["ledgr"])  # LEDGR dates are rewrite stamps, so they go last
    top = order[0]
    given = formal(top["given"])
    family = top["family"]

    def restore(part, kind):
        if not part or any(ord(c) > 127 for c in part):
            return part
        for o in members:
            cand = formal(o["given"]) if kind == "given" else o["family"]
            if any(ord(c) > 127 for c in cand) and name_dist(part, cand) == 0:
                return fix_case(cand)
        return part

    given = restore(fix_case(given), "given")
    family = restore(fix_case(family), "family")

    dobs = {r["dob"] for r in members if r["dob"]}
    assert len(dobs) <= 1, (members, dobs)
    country = next((r["country"] for r in order if r["country"]), None)
    phone = next((r["phone"] for r in order if r["phone"]), None)
    bal = next((r["bal"] for r in order if r["bal"] is not None), None)
    amount = None
    if bal is not None:
        amount = float(round_half_away(to_usd(bal[0], bal[1])))

    records.append(dict(
        entity_id=min(r["row"] for r in members),
        source_rows=sorted(r["row"] for r in members),
        given_name=given, family_name=family,
        birth_date=next(iter(dobs)) if dobs else None,
        country=country, phone_e164=phone, amount_usd=amount))

records.sort(key=lambda r: r["entity_id"])
for r in records:
    print(r["entity_id"], r["source_rows"], r["given_name"], r["family_name"],
          r["birth_date"], r["country"], r["phone_e164"], r["amount_usd"])
print("records:", len(records), "live rows:", len(live),
      "rows covered:", sum(len(r["source_rows"]) for r in records))

with open(OUT, "w", encoding="utf-8") as fh:
    json.dump({"records": records}, fh, ensure_ascii=False, indent=2)
    fh.write("\n")

